// Insert a front-cover APIC frame into the ID3 tag generated by our MP3 muxer.
export function attachArtwork(mp3:Uint8Array,jpeg:Uint8Array):Uint8Array {
  const validHeader=mp3[0]===73&&mp3[1]===68&&mp3[2]===51&&(mp3[3]===3||mp3[3]===4)&&mp3[5]===0;
  if(!validHeader||mp3.length<10||jpeg.length<4||jpeg.length>262144||jpeg[0]!==255||jpeg[1]!==216||
    jpeg.at(-2)!==255||jpeg.at(-1)!==217)throw Error('unsupported');
  const size=(n:number,safe:boolean)=>safe?[(n>>>21)&127,(n>>>14)&127,(n>>>7)&127,n&127]:
    [(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];
  const old=mp3.slice(6,10);
  if(old.some(v=>v>127))throw Error('invalid');
  const oldSize=old.reduce((acc,n)=>acc*128+n,0);
  if(oldSize+10>mp3.length)throw Error('invalid');
  // Latin-1, image/jpeg + NUL, front cover, empty description + NUL.
  const descriptor=[0,105,109,97,103,101,47,106,112,101,103,0,3,0];
  const payload=descriptor.length+jpeg.length,extra=10+payload;
  const output=new Uint8Array(mp3.length+extra);
  output.set(mp3.subarray(0,6));output.set(size(oldSize+extra,true),6);
  output.set([65,80,73,67,...size(payload,mp3[3]===4),0,0,...descriptor],10);
  output.set(jpeg,20+descriptor.length);output.set(mp3.subarray(10),10+extra);
  return output;
}
